import {controller, target} from '@github/catalyst'

@controller('copilot-business-settings-toggle')
export class CopilotBusinessSettingsToggleElement extends HTMLElement {
  @target declare settingForm: HTMLFormElement
  @target declare settingInput: HTMLInputElement
  @target declare settingCheckbox: HTMLInputElement

  toggleSetting() {
    // make sure you have set your targets
    if (!this.settingForm || !this.settingCheckbox || !this.settingInput) return

    if (this.settingCheckbox.getAttribute('data-checked') === 'false') {
      this.settingInput.value = 'enabled'
    } else {
      this.settingInput.value = 'disabled'
    }
  }
}
